using GestionTubos.Application.Interfaces;using GestionTubos.Domain.Entities;using GestionTubos.Domain.Enums;using GestionTubos.Infrastructure.Data;using GestionTubos.Shared.Tubos;using Microsoft.EntityFrameworkCore;
namespace GestionTubos.Infrastructure.Services;
public sealed class TuboService(GestionTubosDbContext db):ITuboService
{
 public async Task UbicarPropiosAsync(TubosUbicarDto dto,string usuario,CancellationToken ct)
 {
  if(dto.Tubos is null || dto.Tubos.Count is < 1 or > 500)throw new InvalidOperationException("Seleccioná entre 1 y 500 tubos.");
  var ids=dto.Tubos.Select(x=>x.Id).ToArray();
  if(ids.Distinct().Count()!=ids.Length)throw new InvalidOperationException("Hay tubos repetidos en la selección.");
  await using var transaccion=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable,ct);
  if(!await db.Ubicaciones.AnyAsync(x=>x.Id==dto.UbicacionDestinoId&&x.EsInterna&&x.GasBateria==null,ct))throw new InvalidOperationException("Seleccioná una ubicación interna activa.");
  var tubos=await db.Tubos.Include(x=>x.Ubicacion).Where(x=>ids.Contains(x.Id)).ToListAsync(ct);
  if(tubos.Count!=ids.Length)throw new InvalidOperationException("Algún tubo ya no existe o fue dado de baja. Actualizá la lista.");
  foreach(var tubo in tubos)
  {
   if(tubo.TipoPropietario!=TipoPropietarioTubo.Empresa)throw new InvalidOperationException("Solo se pueden asignar tubos propios de Oxígeno Norte.");
   if(!tubo.Ubicacion.EsInterna || tubo.EstadoDisponibilidad is not (EstadoDisponibilidad.Disponible or EstadoDisponibilidad.PendienteInspeccion or EstadoDisponibilidad.EnMantenimiento or EstadoDisponibilidad.EnPruebaHidraulica))throw new InvalidOperationException($"El tubo {tubo.CodigoInterno} no puede trasladarse: debe estar en planta y sin una carga o salida en curso.");
   if(tubo.UbicacionId!=dto.Tubos.Single(x=>x.Id==tubo.Id).UbicacionOrigenId)throw new InvalidOperationException($"La ubicación de {tubo.CodigoInterno} cambió. Actualizá la lista antes de continuar.");
  }
  foreach(var tubo in tubos.Where(x=>x.UbicacionId!=dto.UbicacionDestinoId))
  {
   var anterior=Estado(tubo);var origen=tubo.UbicacionId;
   tubo.UbicacionId=dto.UbicacionDestinoId;
   db.MovimientosCilindro.Add(new(){TuboId=tubo.Id,Tipo="Traslado interno",UbicacionOrigenId=origen,UbicacionDestinoId=tubo.UbicacionId,EstadoAnterior=anterior,EstadoPosterior=Estado(tubo),UsuarioResponsable=usuario,Observaciones="Asignación de tubos propios desde Rampas y baterías"});
  }
  await db.SaveChangesAsync(ct);
  await transaccion.CommitAsync(ct);
 }
 public async Task<IReadOnlyList<TuboDto>> ObtenerTodosAsync(string? buscar,CancellationToken ct){var q=db.Tubos.AsNoTracking().Include(x=>x.TipoGas).Include(x=>x.CapacidadTubo).Include(x=>x.Ubicacion).Include(x=>x.ClientePropietario).AsQueryable();if(!string.IsNullOrWhiteSpace(buscar)){var s=buscar.Trim();q=q.Where(x=>x.CodigoInterno.Contains(s)||(x.NumeroSerie!=null&&x.NumeroSerie.Contains(s)));}var xs=await q.OrderBy(x=>x.CodigoInterno).ToListAsync(ct);var ids=xs.Select(x=>x.Id).ToArray();var abiertos=(await db.IngresosClientesDetalle.Where(d=>d.FechaRetiroUtc==null&&ids.Contains(d.TuboId)).Select(d=>d.TuboId).ToListAsync(ct)).ToHashSet();var pruebas=await db.PruebasHidraulicas.AsNoTracking().Where(x=>ids.Contains(x.TuboId)).GroupBy(x=>x.TuboId).Select(g=>g.OrderByDescending(x=>x.FechaRealizacion).First()).ToDictionaryAsync(x=>x.TuboId,ct);return xs.Select(x=>{pruebas.TryGetValue(x.Id,out var p);return Mapear(x,p) with {IngresoClienteAbierto=abiertos.Contains(x.Id)};}).ToList();}
 public async Task<TuboDto?> ObtenerAsync(int id,CancellationToken ct){var x=await Base().AsNoTracking().FirstOrDefaultAsync(x=>x.Id==id,ct);if(x is null)return null;var p=await db.PruebasHidraulicas.AsNoTracking().Where(p=>p.TuboId==id).OrderByDescending(p=>p.FechaRealizacion).FirstOrDefaultAsync(ct);return Mapear(x,p) with {IngresoClienteAbierto=await db.IngresosClientesDetalle.AnyAsync(d=>d.TuboId==id&&d.FechaRetiroUtc==null,ct)};}
 public async Task<TuboDto> CrearAsync(TuboGuardarDto dto,CancellationToken ct){await Validar(dto,null,ct);var x=new Tubo();Copiar(dto,x);if(x.TipoPropietario==TipoPropietarioTubo.Empresa)x.EstadoContenido=EstadoContenido.Lleno;if(x.TipoPropietario==TipoPropietarioTubo.Cliente){x.EstadoDisponibilidad=EstadoDisponibilidad.EnPoderCliente;x.UbicacionId=await UbicacionesSistema.ObtenerEnPoderDelClienteAsync(db,ct);}db.Add(x);await db.SaveChangesAsync(ct);if(dto.RegistrarPruebaInicial)db.PruebasHidraulicas.Add(NuevaPrueba(x.Id,dto));db.MovimientosCilindro.Add(new(){TuboId=x.Id,Tipo="Alta",UbicacionDestinoId=x.UbicacionId,EstadoPosterior=Estado(x),Observaciones="Alta de tubo con prueba hidráulica registrada"});await db.SaveChangesAsync(ct);return (await ObtenerAsync(x.Id,ct))!;}
 public async Task<TuboDto?> ActualizarAsync(int id,TuboGuardarDto dto,CancellationToken ct){var x=await db.Tubos.FirstOrDefaultAsync(x=>x.Id==id,ct);if(x is null)return null;if(x.EstadoDisponibilidad is EstadoDisponibilidad.PreparadoParaCarga or EstadoDisponibilidad.EnviadoACarga or EstadoDisponibilidad.EnBateria)throw new InvalidOperationException("El tubo tiene una carga o batería en curso. Gestioná su estado desde esa operación.");if(x.EstadoDisponibilidad is EstadoDisponibilidad.Reservado or EstadoDisponibilidad.EnReparto)throw new InvalidOperationException("El tubo tiene una entrega pendiente. Corregí primero el remito.");if(await db.IngresosClientesDetalle.AnyAsync(d=>d.TuboId==id&&d.FechaRetiroUtc==null,ct)&&(dto.TipoPropietario!=(int)x.TipoPropietario||dto.ClientePropietarioId!=x.ClientePropietarioId))throw new InvalidOperationException("No se puede cambiar el propietario mientras el tubo está recibido en planta.");if(((int)x.TipoPropietario!=dto.TipoPropietario||x.ClientePropietarioId!=dto.ClientePropietarioId)&&await db.OperacionesCilindro.AnyAsync(o=>o.TuboId==id&&o.FechaDevolucionUtc==null,ct))throw new InvalidOperationException("No se puede cambiar el propietario mientras el tubo tiene una entrega activa.");await Validar(dto,id,ct);var anterior=Estado(x);var origen=x.UbicacionId;var tipoAnterior=x.TipoPropietario;var disponibilidadAnterior=x.EstadoDisponibilidad;var ubicacionAnterior=x.UbicacionId;var estabaEnPlanta=await db.Ubicaciones.AnyAsync(u=>u.Id==ubicacionAnterior&&u.EsInterna&&u.GasBateria==null,ct);Copiar(dto,x);if(x.TipoPropietario==TipoPropietarioTubo.Cliente){x.EstadoDisponibilidad=tipoAnterior==TipoPropietarioTubo.Cliente||estabaEnPlanta?disponibilidadAnterior:EstadoDisponibilidad.EnPoderCliente;x.UbicacionId=tipoAnterior==TipoPropietarioTubo.Cliente||estabaEnPlanta?ubicacionAnterior:await UbicacionesSistema.ObtenerEnPoderDelClienteAsync(db,ct);}if(dto.RegistrarPruebaInicial){var ultima=await db.PruebasHidraulicas.Where(p=>p.TuboId==id).OrderByDescending(p=>p.FechaRealizacion).FirstOrDefaultAsync(ct);if(ultima is null||ultima.FechaRealizacion!=dto.FechaPruebaHidraulica||ultima.FechaVencimiento!=dto.FechaVencimientoPrueba)db.PruebasHidraulicas.Add(NuevaPrueba(id,dto));}if(x.TipoPropietario==TipoPropietarioTubo.Cliente&&x.EstadoDisponibilidad is (EstadoDisponibilidad.PendienteInspeccion or EstadoDisponibilidad.EnPruebaHidraulica)&&dto.RegistrarPruebaInicial&&dto.PruebaAprobada&&dto.FechaVencimientoPrueba>=DateOnly.FromDateTime(GestionTubos.Shared.HoraArgentina.Hoy)&&x.EstadoFisico is not(EstadoFisico.Danado or EstadoFisico.Inutilizable))x.EstadoDisponibilidad=EstadoDisponibilidad.Disponible;db.MovimientosCilindro.Add(new(){TuboId=x.Id,Tipo="Actualización",UbicacionOrigenId=origen,UbicacionDestinoId=x.UbicacionId,EstadoAnterior=anterior,EstadoPosterior=Estado(x),Observaciones="Actualización desde ficha del tubo"});await db.SaveChangesAsync(ct);return await ObtenerAsync(id,ct);}
 public async Task<bool> EliminarAsync(int id,CancellationToken ct){var x=await db.Tubos.FirstOrDefaultAsync(x=>x.Id==id,ct);if(x is null)return false;if(x.EstadoDisponibilidad is EstadoDisponibilidad.PreparadoParaCarga or EstadoDisponibilidad.EnviadoACarga or EstadoDisponibilidad.EnBateria)throw new InvalidOperationException("No se puede dar de baja un tubo vinculado a una carga o batería en curso.");if(await db.IngresosClientesDetalle.AnyAsync(d=>d.TuboId==id&&d.FechaRetiroUtc==null,ct))throw new InvalidOperationException("No se puede dar de baja un tubo de cliente que permanece recibido en planta.");var anterior=Estado(x);x.Activo=false;x.EstadoDisponibilidad=EstadoDisponibilidad.DadoDeBaja;db.MovimientosCilindro.Add(new(){TuboId=x.Id,Tipo="Baja",UbicacionOrigenId=x.UbicacionId,EstadoAnterior=anterior,EstadoPosterior=Estado(x),Observaciones="Baja lógica"});await db.SaveChangesAsync(ct);return true;}
 private IQueryable<Tubo> Base()=>db.Tubos.Include(x=>x.TipoGas).Include(x=>x.CapacidadTubo).Include(x=>x.Ubicacion).Include(x=>x.ClientePropietario);
 private async Task Validar(TuboGuardarDto d,int? id,CancellationToken ct){if(d.EstadoDisponibilidad==13||await db.Ubicaciones.AnyAsync(u=>u.Id==d.UbicacionId&&u.GasBateria!=null,ct))throw new InvalidOperationException("Para incorporar un tubo a una planchada usá Planchadas y baterías.");var codigo=d.CodigoInterno.Trim();if(await db.Tubos.AnyAsync(x=>x.Id!=id&&x.CodigoInterno==codigo,ct))throw new InvalidOperationException("Ya existe un tubo con ese código de serie.");if(d.TipoPropietario==2&&(!d.ClientePropietarioId.HasValue||!await db.Clientes.AnyAsync(c=>c.Id==d.ClientePropietarioId,ct)))throw new InvalidOperationException("Seleccioná el cliente propietario.");if(d.TipoPropietario!=2&&!await db.Ubicaciones.AnyAsync(x=>x.Id==d.UbicacionId,ct))throw new InvalidOperationException("Seleccioná una ubicación válida.");}
 private static void Copiar(TuboGuardarDto d,Tubo x){x.CodigoInterno=d.CodigoInterno.Trim();x.NumeroSerie=L(d.NumeroSerie);x.IdentificacionGrabada=L(d.IdentificacionGrabada);x.TipoGasId=d.TipoGasId;x.CapacidadTuboId=d.CapacidadTuboId;x.Marca=L(d.Marca);x.Fabricante=L(d.Fabricante);x.FechaFabricacion=d.FechaFabricacion;x.TipoPropietario=(TipoPropietarioTubo)d.TipoPropietario;x.ClientePropietarioId=d.TipoPropietario==2?d.ClientePropietarioId:null;x.NombrePropietarioExterno=d.TipoPropietario is 3 or 4?L(d.NombrePropietarioExterno):null;x.EstadoFisico=(EstadoFisico)d.EstadoFisico;x.EstadoContenido=(EstadoContenido)d.EstadoContenido;x.EstadoDisponibilidad=(EstadoDisponibilidad)d.EstadoDisponibilidad;x.UbicacionId=d.UbicacionId;x.Observaciones=L(d.Observaciones);}
 private static string? L(string?x)=>string.IsNullOrWhiteSpace(x)?null:x.Trim();
 private static string Estado(Tubo x)=>$"Físico={(int)x.EstadoFisico};Contenido={(int)x.EstadoContenido};Disponibilidad={(int)x.EstadoDisponibilidad};Ubicación={x.UbicacionId}";
 private static PruebaHidraulica NuevaPrueba(int tuboId,TuboGuardarDto d)=>new(){TuboId=tuboId,FechaRealizacion=d.FechaPruebaHidraulica,FechaVencimiento=d.FechaVencimientoPrueba,Aprobada=true,EntidadRealizadora=string.IsNullOrWhiteSpace(d.EntidadPrueba)?"No especificada":d.EntidadPrueba.Trim()};
 private static TuboDto Mapear(Tubo x,PruebaHidraulica? p=null)=>new(x.Id,x.CodigoInterno,x.NumeroSerie,x.TipoGasId,x.TipoGas.Nombre,x.CapacidadTuboId,$"{x.CapacidadTubo.Valor} {x.CapacidadTubo.Unidad}",(int)x.TipoPropietario,x.ClientePropietarioId,x.TipoPropietario==TipoPropietarioTubo.Empresa?"Oxígeno Norte":x.TipoPropietario==TipoPropietarioTubo.Cliente?x.ClientePropietario?.RazonSocial??$"{x.ClientePropietario?.Apellido}, {x.ClientePropietario?.Nombre}":x.NombrePropietarioExterno??"Sin especificar",(int)x.EstadoFisico,(int)x.EstadoContenido,(int)x.EstadoDisponibilidad,x.UbicacionId,x.Ubicacion.Nombre,x.Marca,x.Fabricante,x.FechaFabricacion,x.IdentificacionGrabada,x.NombrePropietarioExterno,x.Observaciones,p?.FechaRealizacion,p?.FechaVencimiento);
}
